(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+y)*0.01-t*0.15)*8 + Math.cos((x-y)*0.012+t*0.22)*6;
  const w2y = Math.cos((x-y)*0.01+t*0.18)*8 + Math.sin((x+y)*0.013-t*0.28)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 1],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 3],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 4],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 5],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+4)*55, 0.11, 2.1, 6],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75)*65, 0.085, 1.8, 7]
  ];
  let aS = 0, iS = 0, harm = 0;
  for (const [sX, sY, f, sp, idx] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    harm += Math.sin(d*f*0.5 - t*sp*0.4 + idx*0.785) * Math.cos(d*f*0.3 + t*sp*0.3);
  }
  const act = aS/8, inh = iS/8, hrm = harm/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const moire = Math.sin(dist*0.08)*Math.sin(ang*5-t*0.8)*0.3;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + hrm*0.4 + moire)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const dfx = Math.sin(sx*0.008+t*0.1)*20, dfy = Math.cos(sy*0.008-t*0.12)*20;
  const fbm = (Math.sin((sx+dfx)*0.06+t*0.5)*Math.sin((sy+dfy)*0.06-t*0.4) + Math.sin((sx-dfx)*0.04-t*0.6)*Math.cos((sy-dfy)*0.05+t*0.7))*0.25;
  const edge = Math.abs(reaction) > 0.65 ? (1.0 + (Math.abs(reaction)-0.65)*1.2) : Math.abs(reaction)*0.3 + 0.2;
  const blend = reaction*0.55 + cell*0.2 + fbm*0.25;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5));
  const pal = [
    [5,10,45],[12,35,85],[18,70,120],[20,120,130],[45,165,135],
    [140,190,100],[210,185,60],[225,140,55],[200,90,65],[160,50,75],
    [90,25,65],[40,15,55],[5,10,45]
  ];
  const idx2 = v*(pal.length-1), i = Math.min(idx2|0, pal.length-2), f = idx2-i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25;
  const glow = Math.max(0, Math.abs(reaction)-0.8)*5;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*80)|0)
  ];
}
